     "text": "الفرق الصافي −289 وحدة رقم جيد لكنه يخفي فروقاً متقابلة قدرها 14,410 وحدة أي 8.96% من رصيد المداد — طرابلس 11.66% مقابل بنغازي 8.00%، والأصناف المطابقة تماماً في طرابلس 62 صنفاً فقط أي 8.4% مقابل 426 صنفاً في بنغازي أي 43.4%. ويحصر التقرير ثلاث تحفظات نعلنها قبل أن نُسأل عنها: أولاً 149 سطراً في بنغازي بإجمالي 27,383 وحدة — 23% من مخزون الفرع — مُطابَقة على مستوى المجموعة لا صنفاً بصنف لأن كشف المالية دمج أصنافاً متشابهة الأسماء، فأي خطأ توزيع داخلي يُلغي نفسه ولا يظهر، ورقم 251 وحدة فرقاً متبقياً في بنغازي هو حدٌّ أدنى لا أقصى. وثانياً إعادة الترصيد في 113 صنفاً من أصل 126 جاء «الإجمالي المعتمد» فيها مساوياً تماماً لكمية المالية، فالمطابقة بعدها دائرية إلى حدٍّ كبير وتحتاج محاضر عدّ موثقة بالتاريخ والعادّ والموقع. وثالثاً 289 صنفاً لم يُمسح إطلاقاً، ومنها 78 صنفاً برصيد مداد قائم بـ1,717 وحدة — فهذه ثغرة تغطية جرد لا عجز مخزون، والمطلوب جردها لا التحقيق فيها. الخلاصة التنفيذية: المعالجة تستوجب ضبطاً جذرياً لحركة المخزون اليومية، لا تسوية مخزنية."
